$a=Get-NetAdapter|Where-Object Status -eq Up|Select-Object -First 1;if($a){Write-Host ('Adaptador: '+$a.InterfaceDescription);Write-Host ('Velocidad enlace: '+$a.LinkSpeed)};$g=(Get-NetRoute -DestinationPrefix '0.0.0.0/0'|Sort-Object RouteMetric|Select-Object -First 1).NextHop;if($g){$p=Test-Connection $g -Count 10 -ErrorAction SilentlyContinue;if($p){Write-Host ('Gateway: '+$g+' | ping medio '+[math]::Round(($p|Measure ResponseTime -Average).Average,1)+' ms')}};$p=Test-Connection 1.1.1.1 -Count 10 -ErrorAction SilentlyContinue;if($p){Write-Host ('Internet 1.1.1.1: '+[math]::Round(($p|Measure ResponseTime -Average).Average,1)+' ms')}
